), indices AS (
 SELECT column1 AS lo,column2 AS hi,column3*60 AS m,column4*60 AS f
 FROM (VALUES (18,34,175,205),(35,39,180,210),(40,44,185,215),(45,49,195,225),
 (50,54,200,230),(55,59,210,240),(60,64,230,260),(65,69,245,275),(70,74,260,290),
 (75,79,275,305),(80,120,290,320)) v
), nomes AS (SELECT column1 AS numero,column2 AS nome FROM (VALUES (1,'TIAGO RODRIGO DE LIMA'),(17,'ANTONIO MARCO PEREIRA DE ARAUJO'),(31,'REJANE ESTER BISPO DA SILVA'),(1670,'J EDUARDO ZDANOWICZ'),(40630,'FELIPE DE SOUSA MENEZES'),(42213,'MARIA PAULA LOPES'),(42307,'VICTORIA HALLEY DE OLIVEIRA'),(43429,'SOFIA SERAFIM MATTOSINHO'),(43442,'DIEGO VILA'),(44107,'MATHEUS PATTARO'),(46159,'NAURY TANAKA'),(46188,'MARIA DA APARECIDA FERNANDES'),(46206,'ELENILSA DOS SANTOS AGUILAR'),(46217,'LUZIA MENDONCA')) v
), base AS (
 SELECT x.*,CASE WHEN nascimento_ano>=1997 THEN 'Z' WHEN nascimento_ano>=1981 THEN 'Millennials'
 WHEN nascimento_ano>=1965 THEN 'X' WHEN nascimento_ano>=1946 THEN 'Boomers' ELSE 'Pré-1946' END AS geracao,
 CASE WHEN sexo='M' THEN i.m ELSE i.f END AS limite
 FROM fonte x JOIN indices i ON x.idade_boston BETWEEN i.lo AND i.hi
), bq AS (SELECT *,limite-segundos AS margem FROM base WHERE segundos<=limite)
SELECT jsonb_build_object(
 'universo',jsonb_build_object('concluintes',(SELECT count(*) FROM base),'bq',(SELECT count(*) FROM bq)),
 'geracoes',(SELECT jsonb_agg(to_jsonb(g)) FROM (
 SELECT geracao,count(*) AS concluintes,count(*) FILTER (WHERE segundos<=limite) AS bq,
 count(*) FILTER (WHERE segundos<=limite AND sexo='M') AS bq_m,
 count(*) FILTER (WHERE segundos<=limite AND sexo='F') AS bq_f,
 round(100.0*count(*) FILTER (WHERE segundos<=limite)/(SELECT count(*) FROM bq),2) AS percentual_dos_bq,
 round(100.0*count(*) FILTER (WHERE segundos<=limite)/count(*),2) AS taxa_bq
 FROM base GROUP BY geracao ORDER BY min(nascimento_ano)) g),
 'curiosidades',(SELECT jsonb_build_object('bq_40mais',count(*) FILTER (WHERE idade_prova>=40),
 'bq_50mais',count(*) FILTER (WHERE idade_prova>=50),'bq_60mais',count(*) FILTER (WHERE idade_prova>=60),
 'bq_com_ate_60s_de_folga',count(*) FILTER (WHERE margem<=60),
 'bq_sub3',count(*) FILTER (WHERE segundos<10800),'bq_4hmais',count(*) FILTER (WHERE segundos>=14400),
 'idade_media_prova',round(avg(idade_prova),2),
 'menor_folga_segundos',min(margem),'maior_folga_segundos',max(margem)) FROM bq),
 'sem_bq_sub3',(SELECT count(*) FROM base WHERE segundos<10800 AND segundos>limite),
 'idades_bq',(SELECT jsonb_agg(to_jsonb(e)) FROM (
 SELECT sexo,min(idade_prova) AS menor,max(idade_prova) AS maior FROM bq GROUP BY sexo ORDER BY sexo) e),
 'destaques_identificados',(SELECT jsonb_agg(to_jsonb(d) ORDER BY numero) FROM (
 SELECT n.numero,n.nome,b.sexo,b.geracao,b.idade_prova,b.idade_boston,b.segundos,b.limite,
 b.limite-b.segundos AS margem,b.segundos<=b.limite AS bq FROM nomes n JOIN base b USING (numero)) d)
) AS payload
